+// Keep validation tiny and dependency-free. A thrown ValidationError
+// is caught by the route and turned into a clean 400.
+export class ValidationError extends Error {}
+
+export function requireFields<T>(body: any, fields: (keyof T)[]): T {
+  for (const f of fields) {
+    if (body[f] === undefined || body[f] === null) {
+      throw new ValidationError(`Missing field: ${String(f)}`);
+    }
+  }
+  return body as T;
+}

